<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($title) ?> | CliniBox</title><link rel="stylesheet" href="/CLINIBOX/public/assets/css/patient-dashboard.css"><link rel="stylesheet" href="/CLINIBOX/public/assets/css/profile-menu.css?v=3"><link rel="stylesheet" href="/CLINIBOX/public/assets/css/clinibox.css?v=5"><script src="/CLINIBOX/public/assets/js/profile-menu.js?v=2" defer></script></head>
<body class="patient-dashboard-page"><div class="app-shell patient-shell"><aside class="patient-sidebar"><clinibox-profile-menu data-label="Portal del paciente" data-profile="paciente/perfil"></clinibox-profile-menu><nav aria-label="Navegación del paciente"><div class="nav-list"><a href="/CLINIBOX/public/paciente/inicio">Resumen del paciente</a><a href="/CLINIBOX/public/citas">Agendar cita</a><a href="/CLINIBOX/public/paciente/consultas" class="active" aria-current="page">Citas agendadas</a><a href="/CLINIBOX/public/paciente/medicamentos">Farmacia</a><a href="/CLINIBOX/public/paciente/recetas">Recetas</a><a href="/CLINIBOX/public/paciente/mensajes">Mensajes</a></div></nav></aside>
<main class="patient-main"><header class="patient-topbar"><h1 class="topbar-section-title">Mis citas</h1></header><section class="glass-panel" style="padding:24px"><div class="card-title-bar"><h3>Citas registradas</h3><a class="btn btn-outline btn-sm" href="/CLINIBOX/public/citas">Solicitar cita</a></div><div class="appointment-items-list" id="appointmentList" aria-live="polite">Cargando citas…</div></section></main></div>
<script src="/CLINIBOX/public/assets/js/clinic-api.js?v=1"></script><script>
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function dateLabel(value){const [y,m,d]=String(value||'').slice(0,10).split('-');return y?`${d}/${m}/${y}`:'';}
(async()=>{const list=document.getElementById('appointmentList');try{const data=await clinicApi('appointments');const appointments=data.appointments||[];list.innerHTML=appointments.map(a=>`<div class="appointment-entry"><div class="ae-date-col"><small>${dateLabel(a.date)}</small><strong>${esc(a.time)}</strong></div><div class="ae-info-col"><strong>${esc(a.doctor)}</strong><p>${esc(a.reason)} · ${esc(a.status)}</p></div><span class="status-tag ${a.status==='Finalizada'?'completed':'confirmed'}">${esc(a.status)}</span></div>`).join('')||'<p>No hay citas registradas.</p>';}catch(error){list.textContent=error.message;}})();
</script></body></html>